/// Applies embedded migrations using the supplied sqlx pool. No Flash binary is required.
pub async fn FlashInitMigrate(pool: &sqlx::SqlitePool) -> Result<(), sqlx::Error> {
    sqlx::query("CREATE TABLE IF NOT EXISTS _flash_migrations (id VARCHAR(255) PRIMARY KEY, checksum VARCHAR(64) NOT NULL, finished_at TIMESTAMP NULL, migration_name VARCHAR(255) NOT NULL, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)").execute(pool).await?;
    for migration in MIGRATIONS {
        let row = sqlx::query("SELECT checksum FROM _flash_migrations WHERE id = $1")
            .bind(migration.id)
            .fetch_optional(pool)
            .await?;
        if let Some(row) = row {
            let checksum: String = row.try_get("checksum")?;
            if checksum != migration.checksum {
                return Err(sqlx::Error::Protocol(format!(
                    "applied migration {} checksum mismatch",
                    migration.id
                )));
            }
            continue;
        }
        let mut tx = pool.begin().await?;
        for statement in migration.statements {
            sqlx::query(sqlx::AssertSqlSafe(*statement))
                .execute(&mut *tx)
                .await?;
        }
        sqlx::query("INSERT INTO _flash_migrations (id, migration_name, checksum, started_at, finished_at) VALUES ($1, $2, $3, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)").bind(migration.id).bind(migration.name).bind(migration.checksum).execute(&mut *tx).await?;
        tx.commit().await?;
    }
    Ok(())
}
